import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"IDEA插件开发环境搭建","description":"","frontmatter":{"title":"IDEA插件开发环境搭建","date":"2020-05-03","categories":["开发工具","编辑器"],"tags":["IDEA"]},"headers":[],"relativePath":"开发工具/IDEA插件开发环境搭建.md","filePath":"开发工具/IDEA插件开发环境搭建.md"}'),t={name:"开发工具/IDEA插件开发环境搭建.md"};function s(d,e,o,c,n,p){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="idea插件开发环境搭建" tabindex="-1">IDEA插件开发环境搭建 <a class="header-anchor" href="#idea插件开发环境搭建" aria-label="Permalink to &quot;IDEA插件开发环境搭建&quot;">​</a></h1><p>本文介绍了手动下载并安装IDEA插件开发环境依赖的过程, 以解决IDEA插件开发环境过程中下载Gradle包过慢的问题<br>如果你的网络环境可以正常下载依赖包, 本文对你来说是通篇废话, 请忽略.</p><h2 id="一依赖" tabindex="-1">一、依赖 <a class="header-anchor" href="#一依赖" aria-label="Permalink to &quot;一、依赖&quot;">​</a></h2><p>由于在国下载内Gradle包的速度较慢，部分大文件会因为下载时间过长连接超时导致下载失败。</p><p>在Idea插件项目中，主要会下载以下三个大文件：</p><ol><li>ideaIC-2020.1.zip （500M左右）</li><li>ideaIC-2020.1-sources.jar （100M左右）</li><li>jbr-11_0_6-linux-x64-b765.25.tar.gz （100M左右）</li></ol><p>下面是<code>ideaIC-2020.1.zip</code>依赖的解决过程，其它依赖的解决过程与之类似。</p><h3 id="1-获取下载链接并手动下载依赖包" tabindex="-1">1. 获取下载链接并手动下载依赖包 <a class="header-anchor" href="#1-获取下载链接并手动下载依赖包" aria-label="Permalink to &quot;1. 获取下载链接并手动下载依赖包&quot;">​</a></h3><p>在命令行下进入Gradle项目根目录，执行下述命令：</p><p><code>./gradlew compileDebugSource --stacktrace -info</code></p><p>在上述日志中找到下载链接，通过迅雷下载。（你也可以直接通过 <a href="#附各依赖包的路径">附录</a> 部分下载）</p><h3 id="2-获取依赖包的sha1码" tabindex="-1">2. 获取依赖包的SHA1码 <a class="header-anchor" href="#2-获取依赖包的sha1码" aria-label="Permalink to &quot;2. 获取依赖包的SHA1码&quot;">​</a></h3><p>使用<code>sha1sum</code>命令获取文件的SHA1码。</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha1sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ideaIC-2020.1.zip</span></span></code></pre></div><p>执行上述命令后，将得到：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cbeeb1f1aebd4c9ea8fb5ab990c5904a676fc41a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ideaIC-2020.1.zip</span></span></code></pre></div><p><code>cbeeb1f1aebd4c9ea8fb5ab990c5904a676fc41a</code>就是<code>ideaIC-2020.1.zip</code>的SHA1码。</p><h3 id="3-在gradle本地缓存的指定路径下创建sha1码同名文件夹将并将依赖包移动至此" tabindex="-1">3. 在gradle本地缓存的指定路径下创建SHA1码同名文件夹，将并将依赖包移动至此 <a class="header-anchor" href="#3-在gradle本地缓存的指定路径下创建sha1码同名文件夹将并将依赖包移动至此" aria-label="Permalink to &quot;3. 在gradle本地缓存的指定路径下创建SHA1码同名文件夹，将并将依赖包移动至此&quot;">​</a></h3><ul><li><p>进入gradle本地缓存的路径</p><p><code>cd ~/.gradle/caches/modules-2/files-2.1</code></p></li><li><p>进入<code>ideaIC-2020.1.zip</code>的所在路径</p><p><code>cd com.jetbrains.intellij.idea/ideaIC/2020.1</code></p></li><li><p>创建SHA1码同名文件夹</p><p><code>mkdir cbeeb1f1aebd4c9ea8fb5ab990c5904a676fc41a</code></p></li><li><p>移动依赖包</p><p><code>cp ~/Downloads/ideaIC-2020.1.zip cbeeb1f1aebd4c9ea8fb5ab990c5904a676fc41a</code></p></li></ul><h3 id="附各依赖包的路径" tabindex="-1">附：各依赖包的路径 <a class="header-anchor" href="#附各依赖包的路径" aria-label="Permalink to &quot;附：各依赖包的路径&quot;">​</a></h3><ol><li><code>com.jetbrains.intellij.idea/ideaIC/2020.1/xxx/ideaIC-2020.1.zip</code> <a href="https://cache-redirector.jetbrains.com/www.jetbrains.com/intellij-repository/releases/com/jetbrains/intellij/idea/ideaIC/2020.1/ideaIC-2020.1.zip" target="_blank" rel="noreferrer">下载</a></li><li><code>com.jetbrains.intellij.idea/ideaIC/2020.1/xxx/ideaIC-2020.1-sources.jar</code> <a href="https://cache-redirector.jetbrains.com/www.jetbrains.com/intellij-repository/releases/com/jetbrains/intellij/idea/ideaIC/2020.1/ideaIC-2020.1-sources.jar" target="_blank" rel="noreferrer">下载</a></li><li><code>com.jetbrains/jbre/jbr-11_0_6-linux-x64-b765.25.tar.gz</code> <a href="https://cache-redirector.jetbrains.com/jetbrains.bintray.com/intellij-jbr/jbr-11_0_6-linux-x64-b765.25.tar.gz" target="_blank" rel="noreferrer">下载</a></li></ol>',21)])])}const u=a(t,[["render",s]]);export{b as __pageData,u as default};
